const fs = require('fs');
const SEEN_FILE = '/data/shared/seen_viewers.json';
let seen = [];
try {
  if (fs.existsSync(SEEN_FILE)) {
    seen = JSON.parse(fs.readFileSync(SEEN_FILE, 'utf8'));
  }
} catch (e) {}

const viewers = $input.first().json.viewers || [];
const newViewers = [];

for (const v of viewers) {
  if (!seen.includes(v.profileUrl)) {
    seen.push(v.profileUrl);
    newViewers.push(v);
  }
}

try {
  fs.writeFileSync(SEEN_FILE, JSON.stringify(seen.slice(-500), null, 2), 'utf8');
} catch (e) {}

if (newViewers.length === 0) {
  return [];
}

return newViewers.map(v => ({ json: v }));

